function empleadoCtrl($scope,mS,toast){$scope.empleados=[],$scope.maxSize=5,$scope.totalRecords=0,$scope.pageIndex=1,$scope.pageSize=10,$scope.recordsQuantity=[5,10,25,50],$scope.resultModal=function(result){"object"==typeof result&&$scope.getEmpleados()},$scope.getEmpleados=function(){try{showLoader(),mS.getData("get","/Empleado/Get?pageIndex="+$scope.pageIndex+"&pageSize="+$scope.pageSize).then(response=>{if("0"==response.id)return hideLoader(),void toast.toastr("warning",response.message,response.titleSms);$scope.empleados=response.data,response.data.length>0&&($scope.totalRecords=response.data[0].totalRecords),hideLoader()})}catch(error){hideLoader(),console.log(error)}},$scope.getEmpleados(),$scope.pagechanged=function(){$scope.getEmpleados()},$scope.changePageSize=function(){$scope.pageIndex=1,$scope.getEmpleados()},$scope.askToDelete=async item=>{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",title:"",html:"<small>Esta seguro/a de eliminar este Empleado <b>"+item.empleado.nombreCompleto+"</b>?</small> ",showDenyButton:!0,confirmButtonText:"Si,eliminar!",denyButtonText:"No, cancelar!",allowOutsideClick:!1});isConfirmed&&(showLoader(),mS.getData("post","/Empleado/Delete?idEmpleado="+item.empleado.idEmpleado).then(response=>{"0"==response.id&&(hideLoader(),toast.toastr("warning",response.message,response.titleSms)),"1"==response.id&&(hideLoader(),toast.toastr("success",response.message,response.titleSms),$scope.getEmpleados())}))}}app.controller("empleadoCtrl",empleadoCtrl),empleadoCtrl.$inject=["$scope","mainService","toastService"];